import secrets
import hashlib


class AccountService:
    def __init__(self) -> None:
        self._accounts: dict[str, dict] = {}  # email -> {password_hash, is_admin}
        self._reset_tokens: dict[str, str] = {}  # token -> email

    @staticmethod
    def _normalize(email: str) -> str:
        return email.strip().lower()

    @staticmethod
    def _hash_password(password: str, salt: bytes) -> str:
        return hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100_000).hex()

    @staticmethod
    def _validate_password(password: str) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        self._validate_password(password)
        norm = self._normalize(email)
        if norm in self._accounts:
            raise ValueError("An account with this email already exists.")
        salt = secrets.token_bytes(16)
        self._accounts[norm] = {
            "salt": salt,
            "password_hash": self._hash_password(password, salt),
            "is_admin": is_admin,
        }

    def login(self, email: str, password: str) -> bool:
        norm = self._normalize(email)
        account = self._accounts.get(norm)
        if account is None:
            return False
        return secrets.compare_digest(
            account["password_hash"], self._hash_password(password, account["salt"])
        )

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester_norm = self._normalize(requester_email)
        target_norm = self._normalize(target_email)

        requester = self._accounts.get(requester_norm)
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets.")

        if target_norm not in self._accounts:
            raise ValueError("Target account does not exist.")

        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target_norm
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        self._validate_password(new_password)
        if token not in self._reset_tokens:
            raise ValueError("Invalid or already-used reset token.")
        target_norm = self._reset_tokens.pop(token)
        account = self._accounts[target_norm]
        salt = secrets.token_bytes(16)
        account["salt"] = salt
        account["password_hash"] = self._hash_password(new_password, salt)
